WITH реестр AS (SELECT d.content FROM project_documents d JOIN scheme($1) r ON r.role = 'register.questions' AND d.entity_name = r.value WHERE d.project_id = $1 AND d.entity_kind = 'index'), сказано AS (SELECT (SELECT (regexp_match(content, o.value || ':\s*([0-9]+)'))[1]::int FROM реестр) AS открытых, (SELECT (regexp_match(content, c.value || ':\s*([0-9]+)'))[1]::int FROM реестр) AS закрытых FROM scheme($1) o, scheme($1) c WHERE o.role = 'register.open' AND c.role = 'register.closed'), факт AS (SELECT count(*) FILTER (WHERE state <> 'closed') AS открытых, count(*) FILTER (WHERE state = 'closed') AS закрытых FROM project_questions WHERE project_id = $1), строк AS (SELECT count(*) AS n FROM project_document_cells c JOIN scheme($1) r ON r.role = 'register.questions' AND c.entity_name = r.value WHERE c.project_id = $1 AND c.entity_kind = 'index' AND c.col = 0 AND c.value ~ coalesce((SELECT value FROM scheme($1) WHERE role = 'id.question' LIMIT 1), (SELECT spec->>'id' FROM kind_layout WHERE name = 'question'), '^Q-')) SELECT 'реестр говорит «открытых ' || s.открытых || '», а в наборе незакрытых ' || f.открытых AS detail FROM сказано s, факт f WHERE s.открытых IS NOT NULL AND s.открытых <> f.открытых UNION ALL SELECT 'реестр говорит «закрытых ' || s.закрытых || '», а в наборе ' || f.закрытых FROM сказано s, факт f WHERE s.закрытых IS NOT NULL AND s.закрытых <> f.закрытых UNION ALL SELECT 'в таблице реестра строк ' || t.n || ', а незакрытых вопросов ' || f.открытых FROM строк t, факт f WHERE t.n <> f.открытых ORDER BY 1
